{
  "name": "opencode-orcaterm-auth",
  "version": "0.2.9",
  "description": "把腾讯云 OrcaTerm（遨驰终端）AI 助手的额度反代成 OpenAI 兼容接口，供 magpie / OpenCode 作为供应商使用",
  "type": "module",
  "main": "./index.mjs",
  "exports": {
    ".": "./index.mjs",
    "./server": "./index.mjs"
  },
  "files": [
    "index.mjs",
    "wechat.mjs",
    "login.mjs",
    "import-cookies.mjs",
    "probe.mjs",
    "PUBLISH.md",
    "LICENSE",
    "README.md",
    "CHANGELOG.md"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "magpie",
    "orcaterm",
    "tencent",
    "provider"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/hg1048596-pixel/opencode-orcaterm-auth.git"
  },
  "homepage": "https://github.com/hg1048596-pixel/opencode-orcaterm-auth#readme",
  "bugs": {
    "url": "https://github.com/hg1048596-pixel/opencode-orcaterm-auth/issues"
  },
  "magpie": {
    "maxConcurrency": 1,
    "icon": "data:image/png;base64,"
  },
  "scripts": {
    "probe": "node probe.mjs",
    "login": "node login.mjs",
    "test": "node test/selftest.mjs && node test/edge.mjs && node --test test/audit.test.mjs test/usage.test.mjs test/identity.test.mjs",
    "test:selftest": "node test/selftest.mjs",
    "test:edge": "node test/edge.mjs"
  },
  "engines": {
    "node": ">=18"
  }
}
